class Solution {
  public int countGoodRotations(int[] nums) {
    int n = nums.length, h = n / 2;
    long[] pre = new long[2 * n + 1];
    for (int i = 0; i < 2 * n; i++) pre[i + 1] = pre[i] + nums[i % n];
    long total = pre[n];
    int count = 0;
    for (int k = 0; k < n; k++) {
      long first = pre[k + h] - pre[k];
      if (2 * first > total) count++;
    }
    return count;
  }
}
